// Lora (SIL Open Font License) — static instances extracted from the
// variable font and subset to Latin + common punctuation, embedded for
// use as a nicer book-style serif in the generated PDF.
const LORA_FONTS = {
  normal: "",
  bold: "",
  italic: "",
  bolditalic: "",
};

function registerLoraFont(doc) {
  doc.addFileToVFS('Lora-Regular.ttf', LORA_FONTS.normal);
  doc.addFont('Lora-Regular.ttf', 'lora', 'normal');
  doc.addFileToVFS('Lora-Bold.ttf', LORA_FONTS.bold);
  doc.addFont('Lora-Bold.ttf', 'lora', 'bold');
  doc.addFileToVFS('Lora-Italic.ttf', LORA_FONTS.italic);
  doc.addFont('Lora-Italic.ttf', 'lora', 'italic');
  doc.addFileToVFS('Lora-BoldItalic.ttf', LORA_FONTS.bolditalic);
  doc.addFont('Lora-BoldItalic.ttf', 'lora', 'bolditalic');
}